with imported(source_key, vendor_name, name, description, category, price, image_url, is_available, ingredients, allergens, photo_status, image_quality_status, description_quality_status, is_bankable, is_public, status) as (
  values
  ('save-peyia-cote-porc', 'Snack Savè Peyi''A', 'Côte de porc riz crudités', 'Côte de porc grillée au feu de bois, tendre et savoureuse, servie avec du riz blanc parfumé et des crudités fraîches. Le plat signature de Snack Savè Peyi''A, un régal généreux fait maison ! 🔥', 'Plats', 12, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0005.jpg', true, 'Côte de porc grillée, riz blanc, salade verte, tomate, sauce maison.', 'À confirmer avec le prestataire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-filet-poulet', 'Snack Savè Peyi''A', 'Filet de poulet', 'Filet de poulet grillé aux herbes, mariné maison, accompagné de riz parfumé, lentilles pays, légumes et crudités fraîches. Sain, généreux, fait maison avec amour ! 🐔', 'Plats', 10, null, true, 'Filet de poulet grillé, accompagné de riz, lentilles, légumes pays et crudités.', 'À confirmer avec le prestataire.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('save-peyia-crevettes', 'Snack Savè Peyi''A', 'Crevettes riz crudités', 'Crevettes sautées aux épices locales et oignons, servies avec du riz blanc et une salade fraîche croquante. Un plat léger et savoureux, parfait pour découvrir les saveurs de Snack Savè Peyi''A ! 🦐', 'Plats', 14, null, true, 'Crevettes sautées, oignons, tomates, riz blanc, salade verte, tomate, sauce maison.', 'Crustacés.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('save-peyia-cote-agneau', 'Snack Savè Peyi''A', 'Côte d''agneau', 'Côte d''agneau grillée aux épices, fondante et parfumée, servie avec frites maison, gratin, légumes pays ou riz au choix.', 'Plats', 16, null, true, 'Côte d''agneau grillée. Accompagnements : frites, gratin, légumes pays, riz, lentilles, bananes frites, crudités.', 'À confirmer avec le prestataire.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('save-peyia-entrecote', 'Snack Savè Peyi''A', 'Entrecôte', 'Entrecôte grillée, cuisson maîtrisée, servie avec frites maison croustillantes, gratin, légumes pays ou riz au choix. 🥩', 'Plats', 18, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0008.jpg', true, 'Entrecôte grillée. Accompagnements : frites, gratin, légumes pays, riz, lentilles, bananes frites, crudités.', 'À confirmer avec le prestataire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-bavette', 'Snack Savè Peyi''A', 'Bavette de bœuf', 'Bavette de bœuf grillée, tendre et savoureuse, accompagnée de frites maison, gratin, légumes pays ou riz au choix.', 'Plats', 15, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0009.jpg', true, 'Bavette de bœuf grillée. Accompagnements : frites, gratin, légumes pays, riz, lentilles, bananes frites, crudités.', 'À confirmer avec le prestataire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-cabri', 'Snack Savè Peyi''A', 'Cabri', 'Cabri grillé aux épices créoles, une spécialité antillaise généreuse, servie avec frites, gratin, légumes pays ou riz au choix. 🐐', 'Plats', 16, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0010.jpg', true, 'Cabri grillé. Accompagnements : frites, gratin, légumes pays, riz, lentilles, bananes frites, crudités.', 'À confirmer avec le prestataire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-panini-saumon', 'Snack Savè Peyi''A', 'Panini saumon', 'Panini chaud garni de saumon, laitue, fromage râpé et sauce maison, toasté sur place. Idéal pour un déjeuner rapide et gourmand ! 🥪', 'Snacking', 8, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0011.jpg', true, 'Pain panini, saumon, laitue, fromage râpé, sauce maison.', 'Gluten, poisson, produits laitiers.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-cocktail-fruit', 'Snack Savè Peyi''A', 'Cocktail de fruits', 'Cocktail de fruits frais rafraîchissant — jus naturels, glaçons, citron vert, ananas. Sans alcool. Parfait pour se désaltérer sous le soleil martiniquais ! 🍍🥤', 'Snacking', 6, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0015.jpg', true, 'Jus de fruits frais, glaçons, citron vert, ananas.', 'Aucun.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-cocktail-alcool', 'Snack Savè Peyi''A', 'Cocktail fruits (alcool)', 'Cocktail de fruits frais avec alcool (rhum, punch). Rafraîchissant et festif, idéal pour les soirées vendredi et samedi au Pont de Fer ! 🍹', 'Snacking', 10, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0016.jpg', true, 'Jus de fruits frais, alcool (rhum/punch), glaçons, citron vert, ananas.', 'Alcool. Service réservé aux adultes.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-salade-fruits-assortie', 'Snack Savè Peyi''A', 'Salade de fruits frais', 'Salade de fruits frais de saison — ananas, pastèque, kiwi, raisins — en coupelle. Vitamines et fraîcheur garanties ! 🍉🍍', 'Snacking', 6, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0012.jpg', true, 'Fruits frais de saison (ananas, pastèque, kiwi, raisins).', 'Aucun.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('save-peyia-salade-fruits-rhum', 'Snack Savè Peyi''A', 'Salade de fruits au rhum', 'Salade de fruits frais de saison marinée au rhum arrangé. Une explosion de saveurs antillaises ! Idéal pour les soirées. 🥃', 'Snacking', 10, 'https://delikreol.com/vendors/save-peyia/drive-reimport/IMG-20260710-WA0013.jpg', true, 'Fruits frais de saison, rhum arrangé, glaçons.', 'Alcool. Service réservé aux adultes.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('antjecoco-pepite-gratin-banane', 'An Tjè Coco', 'Pépite façon gratin de banane jaune', 'Pépite artisanale salée façon gratin de banane jaune. Sur précommande du dimanche au mardi 12h, retrait mercredi ou jeudi/vendredi.', 'Plats', 9, null, true, 'Banane jaune, fromage râpé, œuf, épices antillaises, farine. Composition à valider avec la prestataire.', 'À confirmer avec le prestataire.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('antjecoco-pepite-coco-passion', 'An Tjè Coco', 'Pépite coco-passion', 'Pépite artisanale sucrée à la noix de coco et au fruit de la passion. Une douceur antillaise raffinée.', 'Desserts', 8, null, true, 'Noix de coco, fruit de la passion, farine, œufs. Composition à confirmer.', 'Gluten, œufs. Autres allergènes à confirmer.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('antjecoco-rougail-saucisses', 'An Tjè Coco', 'Pépite rougail saucisses', 'Pépite salée au rougail saucisses, une revisite créole de la crêpe gastronomique.', 'Plats', 10, null, true, 'Saucisses, tomate, oignons, épices. Composition à confirmer.', 'Gluten (blé). Sans œufs ni produits laitiers.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('antjecoco-tiramisu-cafe', 'An Tjè Coco', 'Pépite tiramisu café', 'Pépite sucrée façon tiramisu au café. Une fusion italo-créole en format bouchée.', 'Desserts', 8, null, true, 'Café, mascarpone, cacao. Composition à confirmer.', 'Gluten, produits laitiers. Autres allergènes à confirmer.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('cocos-food-paella-noire', 'Coco''s Food', 'Paella noire aux fruits de mer', 'Riz noir à l''encre de seiche, généreusement garni de crevettes, moules et morceaux de poisson, relevé de lanières de poivrons jaunes et rouges, petits pois et oignons frais. La spécialité signature de Coco''s Food, un plat marin riche en saveurs et en couleurs.', 'Plats', 15, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0081.jpg', true, 'Riz, encre de seiche, crevettes, moules, poisson blanc, poivrons, oignons, petits pois, épices.', 'Crustacés, mollusques, poisson.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-box-grille', 'Coco''s Food', 'Box grillé du marché', 'Viande de porc grillée marinée aux épices, cuite à la perfection avec une belle croûte caramélisée, servie avec un riz aux pois parfumé, du maïs doux, des carottes râpées et une salade de concombre frais. Un plat généreux relevé d''herbes fraîches.', 'Plats', 12, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0064.jpg', true, 'Viande de porc grillée, riz aux pois, maïs, carottes, concombre, oignons, herbes fraîches, épices.', 'À confirmer avec la partenaire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-poulet-roti', 'Coco''s Food', 'Poulet rôti, riz & crudités', 'Pilons de poulet rôtis à la peau dorée et caramélisée, marinés aux herbes et épices, servis sur un lit de riz assaisonné. Accompagnés de chou rouge croquant, carottes râpées, maïs doux, salade verte et une salsa créole aux oignons et piment frais.', 'Plats', 11, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0066.jpg', true, 'Poulet, riz aux herbes, chou rouge, carottes, maïs, laitue, oignons, piment, épices.', 'À confirmer avec la partenaire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-box-poisson-avocat', 'Coco''s Food', 'Box poisson & avocat', 'Chiquetaille de morue parfumée à l''huile et aux herbes, accompagnée de ti-nains (bananes vertes bouillies) fondants, d''une belle tranche d''avocat bien mûr, d''une salade de concombre et oignons croquants, le tout relevé d''une vinaigrette maison. Servi avec un jus de fruits cocktail artisanal.', 'Plats', 13, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0076.jpg', true, 'Morue effilochée, bananes vertes (ti-nain), avocat, concombre, oignons, herbes, huile, citron, piment.', 'Poisson.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-brochettes', 'Coco''s Food', 'Brochettes panées du marché', 'Pièces panées dorées et croustillantes, servies avec un accompagnement du jour. Plat généreux de marché, à confirmer selon disponibilité.', 'Plats', 12, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0077.jpg', true, 'Pièces panées, accompagnement du jour, herbes et épices. Composition exacte à confirmer avec la partenaire.', 'Gluten possible. Autres allergènes à confirmer.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-friture', 'Coco''s Food', 'Friture caramélisée', 'Bananes plantains mûres frites caramélisées, mélangées à des morceaux de porc ou bœuf frits et des rondelles de saucisse, relevés d''oignons émincés et de piment. Un alloco-viande généreux aux saveurs sucrées-salées irrésistibles.', 'Snacking', 10, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0080.jpg', true, 'Banane plantain, viande de porc ou bœuf, saucisse, oignons, piment, huile, épices.', 'À confirmer avec la partenaire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-plat-jour', 'Coco''s Food', 'Plat du jour complet', 'Bol généreux et équilibré : riz noir djon-djon aux petits pois, poisson ou viande effiloché(e) en sauce tomate épicée, dés de betteraves, salade verte croquante, oignons blancs, carottes râpées, maïs doux et rondelles de banane plantain. Un festival de saveurs et de couleurs qui change chaque jour.', 'Plats', 11, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0082.jpg', true, 'Riz djon-djon, poisson ou viande effiloché(e), betteraves, salade, oignons, carottes, maïs, banane plantain, épices.', 'Poisson. Autres à confirmer.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-salade-viande', 'Coco''s Food', 'Salade de viande marinée', 'Salade fraîche et relevée : dés de viande ou pâté de porc marinés, mélangés à des oignons rouges croquants, de la cébette et du piment rouge frais, le tout assaisonné d''une sauce vinaigrée aux épices et au citron. Parfaite en entrée ou repas léger.', 'Snacking', 8, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0085.jpg', true, 'Viande marinée ou pâté de porc, oignons rouges, cébette, piment, citron, vinaigre, épices.', 'À confirmer avec la partenaire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('cocos-food-spaghetti', 'Coco''s Food', 'Spaghetti sauté', 'Spaghettis sautés aux légumes — poivrons verts et rouges, oignons — et aux saucisses cocktail, relevés d''épices. Un plat de pâtes savoureux et généreux, parfait pour les petits et grands appétits.', 'Plats', 8, 'https://delikreol.com/vendors/coco/drive-reimport/IMG-20260526-WA0071.jpg', true, 'Spaghetti, saucisse cocktail, poivrons, oignons, épices, huile.', 'Gluten. Autres à confirmer.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-attieke', 'Saveurs d''Afrique', 'Attiéké', 'Poisson grillé doré à la perfection, servi sur un lit d''attiéké (semoule de manioc fermentée), accompagné de banane plantain frite (alloco), crudités croquantes (chou, carotte, concombre) et mayonnaise maison. Deux sauces maison complètent le tableau : piment rouge relevé et oignons fondants confits. Un plat complet et parfumé, signature incontournable de la cuisine ivoirienne de rue.', 'Plats', 14, null, true, 'Poisson grillé, attiéké (manioc), banane plantain, chou, carotte, concombre, mayonnaise maison, piment rouge, oignon confit, épices.', 'Poisson, œuf (mayonnaise).', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('saveurs-afrique-foutou', 'Saveurs d''Afrique', 'Foutou banane sauce arachide', 'Foutou — banane plantain pilée à la perfection en une boule dense et élastique, servie avec une sauce arachide onctueuse et parfumée aux épices africaines. Accompagné de viande de mouton ou dinde longuement mijotée. Un grand classique ivoirien riche et réconfortant, où la douceur du plantain rencontre la rondeur de l''arachide.', 'Plats', 15, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0156.jpg', true, 'Banane plantain pilée, pâte d''arachide, viande de mouton ou dinde, tomate, oignon, piment, épices africaines.', 'Arachide.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-ablo', 'Saveurs d''Afrique', 'Ablo (Gâteau de riz)', 'Galettes de riz fermenté cuites à la vapeur, d''un blanc immaculé à la texture spongieuse et légèrement acidulée. Servies avec un poisson entier frit (tilapia) à la peau croustillante et dorée, accompagné d''une sauce tomate-piment rouge intense longuement réduite aux oignons et épices. L''ablo traditionnel ivoirien, doux et aérien, idéal pour absorber les saveurs puissantes de la sauce.', 'Plats', 15, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0155.jpg', true, 'Riz fermenté, maïs, poisson (tilapia), tomate, oignon, piment, huile de palme, épices.', 'Poisson.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-atassi', 'Saveurs d''Afrique', 'Atassi (riz aux haricots)', 'Atassi maison : riz aux haricots, généreux et nourrissant, servi avec sauce et accompagnement du jour selon disponibilité. Un classique simple, complet et réconfortant.', 'Plats', 12, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0158.jpg', true, 'Riz, haricots, sauce maison, épices. Accompagnement du jour à confirmer.', 'À confirmer avec la partenaire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-sauce-legume', 'Saveurs d''Afrique', 'Sauce légume', 'Sauce légume africaine, riche et parfumée, préparée avec feuilles/légumes mijotés et épices. Servie avec l’accompagnement disponible du jour.', 'Plats', 13, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260612-WA0142.jpg', true, 'Feuilles ou légumes mijotés, tomate, oignon, huile, piment, épices. Viande, poisson ou accompagnement à confirmer.', 'À confirmer avec la partenaire.', 'confirmée', 'à valider', 'validée', true, false, 'draft'),
  ('saveurs-afrique-sauce-gombo', 'Saveurs d''Afrique', 'Sauce gombo', 'Sauce gombo onctueuse à la texture filante caractéristique, mijotée aux épices africaines. Servie avec l’accompagnement du jour selon disponibilité.', 'Plats', 13, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0159.jpg', true, 'Gombo, oignon, piment, épices, huile. Protéine et accompagnement à confirmer.', 'À confirmer avec la partenaire.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-igname', 'Saveurs d''Afrique', 'Igname jus d''œuf', 'Igname pilée, lisse et élastique — cette pâte blanche traditionnelle est accompagnée d''une sauce tomate-oignon aux œufs durs, parfumée au piment et aux épices africaines. Un plat réconfortant où la douceur de l''igname rencontre l''acidité de la sauce tomate relevée.', 'Plats', 12, null, true, 'Igname pilée, œufs durs, tomate, oignon, piment, huile, épices.', 'Œufs.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('saveurs-afrique-monyo', 'Saveurs d''Afrique', 'Mônyo', 'Mônyo maison : sauce tomate-oignon relevée aux épices africaines, servie avec l’accompagnement disponible du jour. Plat parfumé, généreux et mijoté.', 'Plats', 12, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260612-WA0141.jpg', true, 'Tomate, oignon, piment, gingembre, ail, épices africaines, huile. Protéine et accompagnement à confirmer.', 'À confirmer avec la partenaire.', 'confirmée', 'à valider', 'validée', true, false, 'draft'),
  ('saveurs-afrique-spaghetti', 'Saveurs d''Afrique', 'Spaghetti', 'Spaghetti cuits al dente, enrobés d''une sauce tomate maison aux légumes frais (carottes, oignons, poivrons) et épices africaines — une version généreuse et parfumée des pâtes, simple et savoureuse.', 'Plats', 10, null, true, 'Pâtes (blé), tomate, carotte, oignon, poivron, épices, herbes.', 'Gluten.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('saveurs-afrique-salade', 'Saveurs d''Afrique', 'Salade béninoise', 'Salade composée fraîche et colorée façon buddha bowl : dés d''avocat fondant, thon émietté rose pâle, tomates juteuses éclatantes, œufs durs parsemés de poivre noir, oignons verts croquants et laitue fraîche. Chaque ingrédient est disposé séparément pour apprécier sa fraîcheur. Idéale pour un déjeuner léger et équilibré.', 'Plats', 10, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0157.jpg', true, 'Laitue, tomate, thon au naturel, œuf dur, avocat, oignon vert, poivre noir.', 'Poisson, œufs.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-bissap', 'Saveurs d''Afrique', 'Jus de bissap', 'Boisson rouge rubis intense à base de fleurs d''hibiscus (Hibiscus sabdariffa), infusée à froid et légèrement sucrée au sucre de canne. Servie bien fraîche sur glaçons avec une tranche d''ananas frais en garniture — la combinaison parfaite pour adoucir l''acidité naturelle du bissap. Naturellement désaltérante et riche en vitamine C.', 'Boissons', 5, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0160.jpg', true, 'Fleurs d''hibiscus, sucre de canne, eau, glaçons, ananas frais.', 'Aucun.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-yaourt', 'Saveurs d''Afrique', 'Yaourt simple 1L', 'Yaourt brassé maison, épais et onctueux, à la texture lisse et brillante. Fabriqué à partir de lait entier et de ferments lactiques. Vendu en pot d''un litre — idéal pour toute la famille, nature ou accompagné de fruits, miel ou confiture.', 'Desserts', 12, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0161.jpg', true, 'Lait entier, ferments lactiques.', 'Lait.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
  ('saveurs-afrique-degue', 'Saveurs d''Afrique', 'Dèguè 1L', 'Yaourt onctueux au couscous fin légèrement sucré — une spécialité maison à la texture unique entre le flan et le yaourt, avec le croquant subtil du couscous. Vendu en pot d''un litre.', 'Desserts', 15, null, true, 'Lait entier, couscous fin, sucre de canne, ferments lactiques.', 'Lait, gluten.', 'à confirmer', 'à valider', 'validée', false, false, 'draft'),
  ('saveurs-afrique-atchonmon', 'Saveurs d''Afrique', 'Atchonmon (Petits cailloux)', 'Atchonmon (Chin Chin) — petits dés de pâte sablée frits, dorés et croustillants, légèrement sucrés à la vanille. Une collation addictive à la texture ferme et friable, parfaite pour accompagner le thé, le café ou pour une pause gourmande à tout moment de la journée.', 'Snacking', 10, 'https://delikreol.com/vendors/saveurs-afrique/drive-reimport/IMG-20260526-WA0164.jpg', true, 'Farine de blé, œuf, sucre, beurre, vanille.', 'Gluten, œufs, lait.', 'confirmée', 'validée', 'validée', true, true, 'verified'),
