), resolved as (
  select i.*, v.id as vendor_id
  from imported i
  join public.vendors v on lower(regexp_replace(coalesce(v.business_name, v.name), '[^a-zA-Z0-9]+', '', 'g')) = lower(regexp_replace(i.vendor_name, '[^a-zA-Z0-9]+', '', 'g'))
)
insert into public.products(source_key, vendor_id, name, description, category, price, image_url, is_available, ingredients, allergens, photo_status, image_quality_status, description_quality_status, is_bankable, is_public, is_demo, status, updated_at)
select source_key, vendor_id, name, description, category, price, image_url, is_available, ingredients, allergens, photo_status, image_quality_status, description_quality_status, is_bankable, is_public, false, status, now()
from resolved
on conflict (source_key) do update set
  vendor_id = excluded.vendor_id,
  name = excluded.name,
  description = excluded.description,
  category = excluded.category,
  price = excluded.price,
  image_url = excluded.image_url,
  is_available = excluded.is_available,
  ingredients = excluded.ingredients,
  allergens = excluded.allergens,
  photo_status = excluded.photo_status,
  image_quality_status = excluded.image_quality_status,
  description_quality_status = excluded.description_quality_status,
  is_bankable = excluded.is_bankable,
  is_public = excluded.is_public,
  is_demo = false,
  status = excluded.status,
  updated_at = now();

-- Approximate municipality/known-area centroids from the repository's partnerGeo map.
-- They support an explicitly approximate distance until a partner validates a precise address.
with geo(business_name, address, latitude, longitude) as (values
  ('Coco''s Food', 'Marché, 97211 Rivière-Pilote, Martinique', 14.4870, -60.9020),
  ('Snack Savè Peyi''A', 'Près du Pont de Fer, Rivière-Pilote, Martinique', 14.4870, -60.9020),
  ('Les Delices de Ninice', 'Barber Shop de Dillon, Fort-de-France', 14.6104, -61.0718),
  ('Sweet Family Traiteur Orianne', 'Les hauts de Dillon, 97200 Fort-de-France', 14.6104, -61.0718),
  ('Chef à Mada', 'Fort-de-France, Martinique', 14.6104, -61.0718),
  ('Saveurs d''Afrique', 'Cluny, Rivière-Salée, Martinique', 14.5100, -60.9650),
  ('An Tjè Coco', 'Fort-de-France, Martinique', 14.6104, -61.0718)
)
update public.vendors v set
  address = geo.address,
  latitude = geo.latitude,
  longitude = geo.longitude,
  location = extensions.st_point(geo.longitude, geo.latitude)::extensions.geography,
  delivery_radius_km = greatest(coalesce(v.delivery_radius_km, 3), 3),
  updated_at = now()
from geo where lower(coalesce(v.business_name, v.name)) = lower(geo.business_name);

update public.vendors
set logo_url = coalesce(logo_url,
  case
    when lower(coalesce(business_name,name)) = lower('Coco''s Food') then 'https://delikreol.com/vendors/coco/profile.svg'
    when lower(coalesce(business_name,name)) = lower('Chef à Mada') then 'https://delikreol.com/vendors/chef-a-mada/logo.jpg'
    else null
  end), updated_at = now()
where lower(coalesce(business_name,name)) in (lower('Coco''s Food'), lower('Chef à Mada'));
